  "No POST endpoint configured for this survey": "\u0644\u0627 \u062a\u0648\u062c\u062f \u0646\u0642\u0637\u0629 \u0646\u0647\u0627\u064a\u0629 POST \u0645\u0647\u064a\u0623\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639",
